/// Looks up a presentation-registry entry by enum name and serialized value.
#[must_use]
pub fn present_enum(enum_name: &str, value: &str, locale: Locale) -> Option<PresentedValue> {
    let entry = PRESENTATIONS
        .iter()
        .find(|item| item.enum_name == enum_name && item.value == value)?;
    let label = match translated_presentation_text(locale, entry.label_key) {
        Some(text) => text.to_owned(),
        None => format_for_locale(locale, english_by_id(entry.label_key)?),
    };
    let description = entry.description_key.and_then(|key| {
        translated_presentation_text(locale, key)
            .map(str::to_owned)
            .or_else(|| english_by_id(key).map(|base| format_for_locale(locale, base)))
    });
    Some(PresentedValue {
        label,
        description,
        icon_key: entry.icon_key,
        tone: entry.tone,
    })
}
